#include "sampler.h"
#include "mpu6050.h"

/* htim3 is generated by CubeMX in main.c (MX_TIM3_Init), we reuse it here
   so there is only one timer handle in the whole project */
extern TIM_HandleTypeDef htim3;
static I2C_HandleTypeDef *sampler_i2c = 0;

static float             sample_data[FFT_N];
static volatile uint32_t sample_cnt = 0;
static volatile uint8_t  sampling = 0;
static uint32_t          fail_cnt = 0;

void Sampler_Init(I2C_HandleTypeDef *hi2c)
{
    sampler_i2c = hi2c;

    /* TIM3 itself is configured by CubeMX: MX_TIM3_Init() sets
         Prescaler = 83, Period = 999
       84MHz (APB1 timer clock) / 84 = 1MHz counter, 1MHz / 1000 = 1kHz
       here we only enable the interrupt and start the counter       */

    HAL_NVIC_SetPriority(TIM3_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(TIM3_IRQn);

    if (HAL_TIM_Base_Start_IT(&htim3) != HAL_OK)
    {
        Error_Handler();
    }
}

void Sampler_Start(void)
{
    sample_cnt = 0;
    fail_cnt = 0;
    sampling = 1;
}

uint8_t Sampler_IsDone(void)
{
    return (sample_cnt >= FFT_N) ? 1 : 0;
}

float *Sampler_Buffer(void)
{
    return sample_data;
}

/* TIM3 interrupt entry, generated file does not define it because
 * TIM3 was not enabled in CubeMX                                   */
void TIM3_IRQHandler(void)
{
    HAL_TIM_IRQHandler(&htim3);
}

/* called by HAL_TIM_IRQHandler for every update event (1kHz) */
void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim)
{
    int16_t ax = 0, ay = 0, az = 0;

    if ((htim->Instance != TIM3) || (sampling == 0))
        return;

    /* one I2C burst read of the 3 accelerometer axes, X axis is used */
    if (MPU6050_ReadAccel(sampler_i2c, &ax, &ay, &az) != 0)
    {
        fail_cnt++;                       /* wiring lost: do not block forever */
        if (fail_cnt >= 20)
        {
            sample_cnt = FFT_N;           /* finish the block with what we have */
            sampling = 0;
        }
        return;
    }
    fail_cnt = 0;

    if (sample_cnt < FFT_N)
    {
        sample_data[sample_cnt] = (float)ax;
        sample_cnt++;
    }

    if (sample_cnt >= FFT_N)
        sampling = 0;
}
